#!/usr/bin/env bash
# Blind checkpoint — twine-src session twine-seed-effort, v1.
# Authored at sitting 2026-09-29-begin-harness-001 from the request alone
# (TARBALL.md 7; PLANNER.md 4). Outcome contracts only. cwd = the staged
# tree, confined, network off. Exit 0 pass; 1 a probe failed (HOLD);
# 2 this script is broken (a failed control, or python3 missing).
# Writes: one private temp directory (mktemp -d), removed on exit.

set -u
export PYTHONDONTWRITEBYTECODE=1
fails=0
pass() { echo "[PASS] $1"; }
fail() { echo "[FAIL] $1"; fails=$((fails + 1)); }
self_error() { echo "[ERROR] checkpoint: $1"; exit 2; }
command -v python3 >/dev/null 2>&1 || self_error "python3 not found on PATH"
TMP="$(mktemp -d 2>/dev/null || true)"
[ -n "$TMP" ] && [ -d "$TMP" ] || { TMP="./.checkpoint-tmp.$$"; mkdir -p "$TMP" || self_error "cannot create a temp dir"; }
trap 'rm -rf "$TMP"' EXIT
echo "checkpoint twine-seed-effort v1: temp dir $TMP (removed on exit); tree writes: none"

# The seed as session 0 landed it (sha256 55de078e…), gzip+base64, the
# baseline for the insertion-only probe.
ORIG_B64=''
printf '%s' "$ORIG_B64" | base64 -d | gzip -dc > "$TMP/orig.md" 2>/dev/null || self_error "could not decode the embedded baseline"
[ "$(sha256sum "$TMP/orig.md" | cut -d' ' -f1)" = "55de078ea9f027e32fae28f0f35f23c95f3b67d28b3505eaee22e7ae465d6ecb" ] || self_error "embedded baseline hash mismatch"

# probe.py: all file-level assertions in one python, one verdict line each.
cat > "$TMP/probe.py" <<'PYEOF'
import re, sys, pathlib
LABELS = ['insertion-only: every line of the landed seed is present in order', 'T11 heading present', "the architect's effort sentence present verbatim (message 5)", 'message 6 present verbatim', 'the five mechanism rows present byte-exact as table lines', 'section 4.5 Effort present', 'TQ-4 present', 'a dated annotation by this session beneath T8', 'a dated annotation by this session beneath T9', 'a dated annotation by this session beneath D16', 'at least four dated annotations by this session beneath the Arc 1 table', 'a dated annotation by this session beneath TQ-1', "a dated annotation by this session beneath 'How the sitting ended'", 'no TODO in the seed']
orig = pathlib.Path(sys.argv[1]).read_text(encoding="utf-8").split("\n")
p = pathlib.Path("twine-seed.md")
def out(ok, label):
    print(("[PASS] " if ok else "[FAIL] ") + label)
    return ok
if not p.exists():
    for l in LABELS: out(False, l)
    sys.exit(0)
try:
    text = p.read_bytes().decode("utf-8")
except UnicodeDecodeError:
    text = None
if text is None:
    for l in LABELS: out(False, l)
    sys.exit(0)
lines = text.split("\n")
# 1. insertion-only: every original line present, in order
i = 0
for l in lines:
    if i < len(orig) and l == orig[i]:
        i += 1
out(i == len(orig), "insertion-only: every line of the landed seed is present in order")
flat = re.sub(r"\s+", " ", text)
def has(s): return re.sub(r"\s+", " ", s) in flat
out(has("T11 — Effort is envelope × policy × mechanisms; twine owns the envelope and the mechanisms, the office holds the policy."), "T11 heading present")
out(has('In my original draft for the harness, I said that an "effort dial" would be really useful. Not like claude\'s effort toggle, but what it would do is things like run workers twice and compare, spawn reflection sessions to refine context, ask old workers questions after the fact, sessions spawned for subtasks like reading or tools to preserve main context etc. Things that would just increase time and compute but would produce refined answers.'), "the architect's effort sentence present verbatim (message 5)")
out(has("> applied, and as assumed"), "message 6 present verbatim")
rows = [
 "| **run twice and compare** | the same request tarball dispatched to k workers; each candidate response gets `bale apply --dry-run` (the read-only validation half) for a mechanical verdict; a **compare** session reads the k diffs + notes and picks or merges; twine applies the winner. Bale already allows k candidates for one sid — only one ever merges | scheduler, Arc 3; the compare session is nisaba's `check` kind generalised | the verdict as a claims block, plus the losers' dry-run verdicts in twine's stream (calibration data bale never sees) |",
 "| **reflection to refine context** | before a build: a read-only session that reads the brief and includes and returns a revised brief and include set — PLANNER.md §2's \"worker-authored brief on request\", scheduled rather than asked for. After a build: reading notes + telemetry for the next session's brief — which is what office's `cleanup`/`digest` already are | scheduler, Arc 3 (`reflect`, a new kind: lands a brief revision) | the revised brief, versioned (derive-don't-rewrite applies) |",
 "| **ask an old worker** | re-warm a finished worker's transcript (D12's append-only prefix makes this cheap), append a question, get an answer with read-only tools at most | runtime, Arc 2 (`twine ask <sid> …`) | the Q/A in twine's log, and in the asker's record (a sitting's notepad) — this is the manual path's \"go back to the old chat tab\" |",
 "| **subtask sessions to preserve context** | a `delegate` tool on the canonical surface: the worker hands a bounded task (read this 12k-line file and answer X; run this tool-heavy exploration) to a child with its own window, gets a digest back; children are runtime-internal, not bale sessions — they land nothing and bill to the parent sid | runtime, Arc 2 (a capability, and the first one that earns T7's \"experimental\" marker) | the digest in the parent's transcript; nothing else by design — it's context hygiene |",
 "| **retry**, **model-v-model** | D16's own: a second attempt, or two models debating a design question in a read-only session | scheduler, Arc 3 | the `corrects:` lineage / the sitting's record |",
]
out(all(any(l.lstrip("> ").rstrip() == r for l in lines) for r in rows), "the five mechanism rows present byte-exact as table lines")
out(has("### 4.5 Effort"), "section 4.5 Effort present")
out(has("TQ-4 — The effort policy's home and the dial's scale"), "TQ-4 present")
ann = re.compile(r"^\[20\d\d-\d\d-\d\d-twine-seed-effort-\d{3}: ")
def annotations_between(start_pat, end_pat):
    s = next((k for k, l in enumerate(lines) if re.match(start_pat, l)), None)
    if s is None: return -1
    e = next((k for k in range(s + 1, len(lines)) if re.match(end_pat, lines[k])), len(lines))
    return sum(1 for l in lines[s:e] if ann.match(l.lstrip()))
out(annotations_between(r"^\*\*T8 — ", r"^\*\*T9 — ") >= 1, "a dated annotation by this session beneath T8")
out(annotations_between(r"^\*\*T9 — ", r"^\*\*T10 — ") >= 1, "a dated annotation by this session beneath T9")
out(annotations_between(r"^\*\*D16 — ", r"^\*\*D17 — ") >= 1, "a dated annotation by this session beneath D16")
out(annotations_between(r"^Row 0's", r"^### 5\.2") >= 4, "at least four dated annotations by this session beneath the Arc 1 table")
out(annotations_between(r"^- \*\*TQ-1 — ", r"^- \*\*TQ-2 — ") >= 1, "a dated annotation by this session beneath TQ-1")
out(annotations_between(r"^### How the sitting ended", r"(?!x)x") >= 1, "a dated annotation by this session beneath 'How the sitting ended'")
out("TODO" not in text, "no TODO in the seed")
PYEOF

# control: the probe must FAIL the unmodified baseline on every change probe
( cd "$TMP" && mkdir -p ctl && cp orig.md ctl/twine-seed.md && cd ctl && python3 "$TMP/probe.py" "$TMP/orig.md" ) > "$TMP/ctl.out" 2>&1 || self_error "control: probe.py crashed on the baseline"
grep -q "^\[PASS\] insertion-only" "$TMP/ctl.out" || self_error "control: insertion-only probe rejected the baseline itself"
grep -q "^\[FAIL\] T11 heading present" "$TMP/ctl.out" || self_error "control: T11 probe passed on the baseline"
grep -q "^\[FAIL\] TQ-4 present" "$TMP/ctl.out" || self_error "control: TQ-4 probe passed on the baseline"
echo "[control] detectors verified against the baseline"

python3 "$TMP/probe.py" "$TMP/orig.md" > "$TMP/probe.out" 2>&1 || self_error "probe.py crashed: $(head -c 400 "$TMP/probe.out")"
cat "$TMP/probe.out"
fails=$(grep -c "^\[FAIL\]" "$TMP/probe.out" || true)
echo "checkpoint twine-seed-effort v1: $fails probe(s) failed"
[ "$fails" -eq 0 ] && exit 0 || exit 1
